package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.annotation.ObjectIdGenerators;
import com.fasterxml.jackson.annotation.ObjectIdResolver;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.JsonPOJOBuilder;
import com.fasterxml.jackson.databind.cfg.DeserializerFactoryConfig;
import com.fasterxml.jackson.databind.deser.BeanDescription;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.deser.std.ThrowableDeserializer;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.SimpleBeanPropertyDefinition;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Unit tests for BeanDeserializerFactory#createBeanDeserializer.
 * Note: Since many methods are protected/internal, we use a spy to control 
 * the execution flow for different branches.
 */
public class BeanDeserializerFactory_createBeanDeserializer_TriageGen2Test {

    private BeanDeserializerFactory factory;
    private BeanDeserializerFactory spyFactory;
    private DeserializationContext ctxt;
    private DeserializationConfig config;
    private JavaType type;
    private BeanDescription beanDesc;
    private TypeFactory typeFactory;

    // Mock classes for testing
    public static class TestBean { public String name; }
    public static class AbstractBean { }
    public static class ConcreteBean extends AbstractBean { }
    public static class ThrowableBean extends Exception { }

    @Before
    public void setUp() {
        factory = new BeanDeserializerFactory(null);
        spyFactory = Mockito.spy(factory);
        ctxt = mock(DeserializationContext.class);
        config = mock(DeserializationConfig.class);
        type = mock(JavaType.class);
        beanDesc = mock(BeanDescription.class);
        typeFactory = TypeFactory.defaultInstance();

        when(ctxt.getConfig()).thenReturn(config);
    }

    @Test
    public void testCreateBeanDeserializer_WithCustomDeserializer() throws JsonMappingException {
        JsonDeserializer<Object> customDeser = new StdDeserializer<Object>(Object.class) {};
        doReturn(customDeser).when(spyFactory)._findCustomBeanDeserializer(any(), any(), any());

        JsonDeserializer<Object> result = spyFactory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(customDeser, result);
        verify(spyFactory, never()).buildThrowableDeserializer(any(), any(), any());
    }

    @Test
    public void testCreateBeanDeserializer_WithThrowableType() throws JsonMappingException {
        doReturn(null).when(spyFactory)._findCustomBeanDeserializer(any(), any(), any());
        when(type.isThrowable()).thenReturn(true);

        JsonDeserializer<Object> mockThrowableDeser = mock(JsonDeserializer.class);
        doReturn(mockThrowableDeser).when(spyFactory).buildThrowableDeserializer(ctxt, type, beanDesc);

        JsonDeserializer<Object> result = spyFactory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(mockThrowableDeser, result);
    }

    @Test
    public void testCreateBeanDeserializer_WithAbstractTypeAndMaterialization() throws JsonMappingException {
        doReturn(null).when(spyFactory)._findCustomBeanDeserializer(any(), any(), any());
        when(type.isThrowable()).thenReturn(false);
        when(type.isAbstract()).thenReturn(true);
        when(type.isPrimitive()).thenReturn(false);

        JavaType concreteType = typeFactory.constructType(ConcreteBean.class);
        doReturn(concreteType).when(spyFactory).materializeAbstractType(ctxt, type, beanDesc);

        BeanDescription newBeanDesc = mock(BeanDescription.class);
        when(config.introspect(concreteType)).thenReturn(newBeanDesc);

        JsonDeserializer<Object> mockBeanDeser = mock(JsonDeserializer.class);
        doReturn(mockBeanDeser).when(spyFactory).buildBeanDeserializer(ctxt, concreteType, newBeanDesc);

        JsonDeserializer<Object> result = spyFactory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(mockBeanDeser, result);
    }

    @Test
    public void testCreateBeanDeserializer_WithStandardDeserializer() throws JsonMappingException {
        doReturn(null).when(spyFactory)._findCustomBeanDeserializer(any(), any(), any());
        when(type.isThrowable()).thenReturn(false);
        when(type.isAbstract()).thenReturn(false);

        JsonDeserializer<Object> stdDeser = mock(JsonDeserializer.class);
        doReturn(stdDeser).when(spyFactory).findStdDeserializer(ctxt, type, beanDesc);

        JsonDeserializer<Object> result = spyFactory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(stdDeser, result);
    }

    @Test
    public void testCreateBeanDeserializer_NotAPotentialBeanType() throws JsonMappingException {
        doReturn(null).when(spyFactory)._findCustomBeanDeserializer(any(), any(), any());
        when(type.isThrowable()).thenReturn(false);
        when(type.isAbstract()).thenReturn(false);
        doReturn(null).when(spyFactory).findStdDeserializer(any(), any(), any());

        // Simulate a type that is not a bean (e.g., String)
        when(type.getRawClass()).thenReturn(String.class);
        doReturn(false).when(spyFactory).isPotentialBeanType(String.class);

        JsonDeserializer<Object> result = spyFactory.createBeanDeserializer(ctxt, type, beanDesc);

        assertNull(result);
    }

    @Test
    public void testCreateBeanDeserializer_BuildBeanDeserializerFallback() throws JsonMappingException {
        doReturn(null).when(spyFactory)._findCustomBeanDeserializer(any(), any(), any());
        when(type.isThrowable()).thenReturn(false);
        when(type.isAbstract()).thenReturn(false);
        doReturn(null).when(spyFactory).findStdDeserializer(any(), any(), any());

        when(type.getRawClass()).thenReturn(TestBean.class);
        doReturn(true).when(spyFactory).isPotentialBeanType(TestBean.class);

        JsonDeserializer<Object> mockBeanDeser = mock(JsonDeserializer.class);
        doReturn(mockBeanDeser).when(spyFactory).buildBeanDeserializer(ctxt, type, beanDesc);

        JsonDeserializer<Object> result = spyFactory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(mockBeanDeser, result);
    }

    @Test
    public void testCreateBeanDeserializer_AbstractTypeNoMaterialization() throws JsonMappingException {
        doReturn(null).when(spyFactory)._findCustomBeanDeserializer(any(), any(), any());
        when(type.isThrowable()).thenReturn(false);
        when(type.isAbstract()).thenReturn(true);
        when(type.isPrimitive()).thenReturn(false);

        // Return null for materialization
        doReturn(null).when(spyFactory).materializeAbstractType(ctxt, type, beanDesc);

        // Should fall through to findStdDeserializer
        doReturn(null).when(spyFactory).findStdDeserializer(any(), any(), any());
        when(type.getRawClass()).thenReturn(AbstractBean.class);
        doReturn(false).when(spyFactory).isPotentialBeanType(AbstractBean.class);

        JsonDeserializer<Object> result = spyFactory.createBeanDeserializer(ctxt, type, beanDesc);

        assertNull(result);
    }

    // Helper to allow spying on protected methods in the same package
    // In a real Jackson environment, these methods are part of the class.
    // Since we are testing the logic of createBeanDeserializer, we mock the internal calls.
}
